{
  "concepts": [
    {
      "conditions": [],
      "definition": "Finite Worker evaluation of whether the exact authorised outcome can be constructed through the smallest coherent causal cone while preserving every affected governing relation and disposing of competing paths. Its basis is sufficient ACTIVATION §1 intake and, where applicable, accepted design-to-execution basis. Its manifold includes affected entities, lifecycles, transformations, authorities, capabilities, algorithms, inputs, outputs, dependencies, interaction seams, failure boundaries and proof obligations. Coordinates bind activation, checkpoint, workspace, inputs, dependencies, configuration, actor envelope, outputs, candidate and evidence. Evidence includes live implementation, tests and their source, analysis, generated artifacts, claimed installed or operational behaviour, reconstruction, mutations and transition evidence. Required competence covers method, domain, implementation, tools, access and finite context.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 935,
          "quote": "| evaluation family | Can the exact authorised outcome be constructed through the smallest coherent causal cone while preserving every affected governing relation and disposing of competing paths? |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F9.%20Derived%20Worker%20frame",
          "start_line": 928
        }
      ],
      "key": "worker_frame",
      "label": "Derived Worker frame"
    },
    {
      "conditions": [],
      "definition": "Bounded Reviewer evaluation of exact claimed subject and basis, satisfaction of applicable method and project relations, competing authority, proof masking, composition boundaries, and evidence-bound severity and technical implications. Its intake includes candidate, claim, governing authorities, scope, exclusions, evidence population, Product-selected severity scale, review carrier and independence conditions. Its manifold includes causal producers and consumers, authority seams, competing paths, claimed failure/recovery/installed/reconstruction surfaces, test and fixture semantics, historical counterexamples and supportable technical triage. Coordinates include candidate, source basis, authority revision, configuration, dependency, evidence population, severity scale, installed subject, review time and Reviewer identity. Evidence is independently acquired from material live authority, implementation, tests, artifacts, history, operations, mutations, replay, reconstruction and reproduced observations. Competence includes method, domain, implementation, assurance, technical triage, tools, access, context, counterexample search and independence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 970,
          "quote": "| evaluation family | Is this the exact claimed subject and basis? Does it satisfy the applicable method and project relations without competing authority, proof masking or an unevaluated composition boundary? For each finding, which evidence-bound severity and technical implications follow? |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F10.%20Derived%20Reviewer%20frame",
          "start_line": 963
        }
      ],
      "key": "reviewer_frame",
      "label": "Derived Reviewer frame"
    },
    {
      "conditions": ["The coordinated branch is selected."],
      "definition": "The profile's bounded assessor or proxy and decision owner: consumes closed results and technical triage against current Product and MVP or release mandates, assigns priority and promotion-boundary effect, and applies an existing disposition within its grant.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1279,
          "quote": "The Executive verifies that every consumed result is still bound to the\ncurrent subject and basis, revalidates the complete Product view and the\ncurrent MVP or release mandate, applies any declared result conjunction",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition%2F7.%20Executive%20disposes%20and%20checkpoints",
          "start_line": 1273
        }
      ],
      "key": "executive_frame",
      "label": "Executive in the coordinated branch"
    },
    {
      "conditions": ["Lawful Worker activation has occurred."],
      "definition": "Exactly one closed Worker result: candidate_ready(exact_subject, transition_evidence, residuals), refused(reason, authority, evidence), incomplete(residuals, evidence, stop_basis), or re_entry_requested(owner, material_relation, evidence). The material relation in re_entry_requested includes its cause, authority or basis. Each variant maps to exactly one core value for the predicate 'a candidate is available'; individual Worker evaluations retain their own core results. The displayed notation is explanatory and mandates no schema.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1184,
          "quote": "  = candidate_ready(exact_subject, transition_evidence, residuals)\n  | refused(reason, authority, evidence)\n  | incomplete(residuals, evidence, stop_basis)\n  | re_entry_requested(owner, material_relation, evidence)",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition%2F3.%20Worker%20returns%20to%20Executive",
          "start_line": 1173
        },
        {
          "end_line": 937,
          "quote": "each evaluation the Worker performed keeps its own core result",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F9.%20Derived%20Worker%20frame",
          "start_line": 937
        }
      ],
      "key": "work_result",
      "label": "WorkerResult"
    },
    {
      "conditions": ["Activation detects a known capability, authority, subject, basis or topology mismatch."],
      "definition": "activation_refusal is returned by the activation relation directly to the Executive, with the cause and the core value assigned by REFERENCE_FRAME §5. No Worker frame is active and no Worker evaluation or Worker result exists for that failed activation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1164,
          "quote": "If activation detects a known capability, authority, subject, basis or\ntopology mismatch, it returns `activation_refusal` directly to the\nExecutive",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition%2F2.%20Executive%20activates%20Worker",
          "start_line": 1159
        }
      ],
      "key": "activation_refusal",
      "label": "Activation refusal"
    },
    {
      "conditions": [],
      "definition": "One closed Reviewer evaluation in the shape owned by EVALUATION §4: frame and activation identity; exact subject, basis, claim, scope, exclusions and evaluated population; Reviewer actor and independence; acquired evidence and ordinary assurance path; core result; findings, counterexamples and adjacent observations; supportable finding-level affected claim, severity, causal assessment and confidence, blast radius, workaround, repair complexity, regression risk and residual uncertainty; invalidation conditions and applicable re-entry owner. Its triage projects over the result algebra; a recommendation is evidence only.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1262,
          "quote": "The Reviewer returns one closed evaluation in the shape of EVALUATION §4,",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition%2F6.%20Reviewer%20returns%20to%20Executive",
          "start_line": 1249
        }
      ],
      "key": "reviewer_result",
      "label": "Closed review result"
    },
    {
      "conditions": [],
      "definition": "Exactly one authorised disposition: accept, local_repair, re_enter or reject. The disposition is the acceptance result; candidate_ready and a satisfied review are not acceptance. ACTIVATION §3 and §5 own disposition semantics, accepted checkpoint and next already-authorised bounded action.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1284,
          "quote": "The disposition\nis the acceptance result; neither `candidate_ready` nor a satisfied review\nresult is acceptance",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition%2F7.%20Executive%20disposes%20and%20checkpoints",
          "start_line": 1282
        }
      ],
      "key": "disposition_outcome",
      "label": "Disposition and acceptance result"
    },
    {
      "conditions": ["The profile's generic set is adopted for Product work."],
      "definition": "Twelve non-hierarchical, potentially overlapping evaluation archetypes in urn:stdo:bounded-context:reference-frame-evaluation, owned by REFERENCE_FRAME under the selected basis. They are not complete frame declarations, components, actors or runtime objects. Same-spelled Product, Owner, Entity, Operator, Install and other concepts in other contexts remain distinct.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1025,
          "quote": "Each\nrow is an evaluation archetype, not a complete frame declaration",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1012
        }
      ],
      "key": "specialist_family_set",
      "label": "Generic specialist frame families"
    },
    {
      "conditions": [],
      "definition": "Evaluates whether one exact current Product claim, outcome, boundary and lifecycle govern the claimed subject without downstream reinterpretation, on current Intent, Product, requirements, acceptance meaning and exact Product coordinates. Product and requirement authorities retain meaning and acceptance; output is bounded evaluation and evidence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1029,
          "quote": "Product and requirement authority keep meaning and acceptance.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1029
        }
      ],
      "key": "product_evaluation_family",
      "label": "Product evaluation family"
    },
    {
      "conditions": [],
      "definition": "Evaluates one exact directed Product relation, preserving source and target roles; Product Definition, Release Cut, Product and Install identities; Development Product role bindings; contracts, authority, lifecycle, evidence boundary and invalidation law. A chain uses bounded edge activations and declared conjunction. Each Product retains meaning; the authorities and contracts cited by the composition relation own the edge. Output is evaluation evidence only.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1030,
          "quote": "A chain is evaluated through bounded edge activations and a declared conjunction.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1030
        }
      ],
      "key": "product_composition_family",
      "label": "Product Composition"
    },
    {
      "conditions": [],
      "definition": "Evaluates whether accepted structural HOW satisfies material constitutional WHAT, closes required design relations and preserves their owners across affected topology. Accepted design under governing Product and requirements owns structure. Outputs may identify satisfaction, contradiction or design re-entry gap, but cannot invent Product truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1031,
          "quote": "The frame may identify satisfaction, contradiction or a design re-entry gap; it cannot invent Product truth.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1031
        }
      ],
      "key": "design_family",
      "label": "Design"
    },
    {
      "conditions": [],
      "definition": "Evaluates one bounded design component and its direct causal dependency cone for preservation of parent contract, internal relations, sibling seams and required outputs. Its accepted boundary owns only its bounded composition decision; parent, sibling, Product, requirement and runtime owners retain their relations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1032,
          "quote": "Parent, sibling, Product, requirement and runtime owners keep their relations.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1032
        }
      ],
      "key": "design_component_family",
      "label": "Design Component"
    },
    {
      "conditions": [],
      "definition": "Evaluates whether a supported public entry or exit performs exactly its assigned validation, selection, transport, refusal and projection while preserving selected interior owners. Product, interface, identity, security and accepted-design authorities define it. Output is a closed evaluation of boundary result or refusal, without recreating interior semantics.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1033,
          "quote": "it does not recreate interior semantics.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1033
        }
      ],
      "key": "public_boundary_family",
      "label": "Public Boundary"
    },
    {
      "conditions": [],
      "definition": "Evaluates one semantic, artifact or runtime entity's exact identity, kind, lifecycle, owner, representation and applicable effect regime. Product, domain, identity, requirement and accepted-design authorities define it; its result remains identity- and lifecycle-bound.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1034,
          "quote": "The frame returns an identity- and lifecycle-bound evaluation.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1034
        }
      ],
      "key": "entity_family",
      "label": "Entity"
    },
    {
      "conditions": [],
      "definition": "Evaluates whether one material operation is an irreducible declared relation over its admitted domain, inputs, outputs, refusals, algebra, effects and lawful compositions. Product, requirements, accepted ontology and design, and the named operation owner define it. Evaluation creates no additional executable plan.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1035,
          "quote": "The frame evaluates it without creating another executable plan.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1035
        }
      ],
      "key": "operator_family",
      "label": "Operator"
    },
    {
      "conditions": [],
      "definition": "Evaluates only authority congruence of one semantic or authority-bearing relation: owner, role kind, subject, scope, basis, lifecycle, refusal invariants and permitted delegation. Existing Product, requirement, identity, accepted-design, release or other named authority retains ownership.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1036,
          "quote": "The frame may evaluate authority congruence only.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1036
        }
      ],
      "key": "owner_family",
      "label": "Owner"
    },
    {
      "conditions": [],
      "definition": "Evaluates an action against its pure, observational, artifact or runtime effect regime, including material commit, failure, retry, recovery, compensation, admission and projection law. Applicable Product, requirement, design, artifact, runtime and admission owners retain decisions; output is effect-bound result and evidence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1037,
          "quote": "The frame returns an effect-bound result and evidence.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1037
        }
      ],
      "key": "effect_family",
      "label": "Effect"
    },
    {
      "conditions": [],
      "definition": "Evaluates normalisation and bounded comparison of a material generic capability or dependency against credible lawful foundations, preserving irreducible local remainder and authority-bearing role. Selection belongs to design-profile capability-and-foundation law and the existing trade-off owner; a foundation acquires no semantic authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1038,
          "quote": "The frame cannot move semantic authority to a foundation.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1038
        }
      ],
      "key": "reuse_foundation_family",
      "label": "Reuse/Foundation"
    },
    {
      "conditions": [],
      "definition": "Evaluates exact selected Product, release, artifact, dependency set, configuration and callable entry through the admitted installed coordinate, independently of mutable source convenience. Product, identity, release, dependency, packaging and accepted-design authorities define the subject; output is installed identity, reachability and refusal evidence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1039,
          "quote": "The frame returns installed identity, reachability and refusal evidence.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1039
        }
      ],
      "key": "install_family",
      "label": "Install"
    },
    {
      "conditions": [],
      "definition": "Evaluates congruence of one exact claim's subject, basis, path, population, oracle, evidence, falsifier, residual boundary and invalidation law. Claim owner defines meaning; testing, assurance, review, Product and release owners define evaluation and acceptance. Output is evidence and closed evaluation, never Product meaning or disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1040,
          "quote": "The frame returns evidence and a closed evaluation result, not Product meaning or disposition.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set",
          "start_line": 1040
        }
      ],
      "key": "proof_family",
      "label": "Proof"
    },
    {
      "conditions": ["A generic frame is recursively refined."],
      "definition": "A frame dependency relation opened only for a material distinction needed to close the parent evaluation. Each child records parent contract, purpose, material entities, identity and lifecycle relations, semantic owners, direct sibling seams, applicable invariants and prohibited competing paths. It is neither an organisational nor a runtime hierarchy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1074,
          "quote": "Refinement opens only for a material\ndistinction needed to close the parent evaluation.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set%2FRefinement%20and%20conjunction",
          "start_line": 1071
        }
      ],
      "key": "frame_refinement",
      "label": "Recursive frame refinement"
    },
    {
      "conditions": [],
      "definition": "Coverage is the union of admissible observations contributed by activated frames. A composite claim receives its declared conjunction's reported value. Every material cross-frame seam is mandatory result or required coverage, preserving or lawfully translating exact identity, coordinate, basis, value or evidence, lifecycle scope, authority and provenance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1086,
          "quote": "Coverage records the union of admissible observations the activated frames\ncontribute.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set%2FRefinement%20and%20conjunction",
          "start_line": 1076
        }
      ],
      "key": "composite_evaluation",
      "label": "Coverage and composite claim"
    },
    {
      "conditions": ["The specialist set is adopted."],
      "definition": "ASSURANCE §7 user-acceptance, end-to-end, integration and unit testing frames supply claim-congruent evidence to one or more Proof evaluations while retaining distinct claims and coordinates. Proof supplies neither a testing hierarchy nor aggregate-green substitution.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1115,
          "quote": "user-acceptance, end-to-end,\nintegration and unit results keep their distinct claims and coordinates",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set%2FRelation%20to%20the%20testing%20and%20interface%20frames",
          "start_line": 1113
        }
      ],
      "key": "testing_frames",
      "label": "Product testing frames"
    },
    {
      "conditions": [],
      "definition": "ASSURANCE §13 end-to-end interface integration connects Public Boundary, Design, Operator, Owner and Proof families to integration, end-to-end and user-acceptance frames. Its computational whole-path evaluation composes selected interface claims with Operator, Owner, Reuse/Foundation and Proof. Neither introduces a thirteenth family, fifth testing type, role or universal activation gate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1122,
          "quote": "Neither adds a thirteenth family, a fifth\ntesting type, a role or a universal activation gate",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F11.%20Derived%20generic%20specialist%20frame%20set%2FRelation%20to%20the%20testing%20and%20interface%20frames",
          "start_line": 1121
        }
      ],
      "key": "interface_integration",
      "label": "End-to-end interface integration"
    },
    {
      "conditions": [],
      "definition": "The described transition sequence is the coordinated branch selected under §3. Direct Worker engagement retains the same sufficient intake, work-result algebra, closure conditions and owner boundaries without inserting an Executive appointment or review not required by an applicable condition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1129,
          "quote": "Direct\nWorker engagement keeps the same sufficient intake, work-result algebra,\nclosure conditions and owner boundaries",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition",
          "start_line": 1126
        }
      ],
      "key": "engagement_transition",
      "label": "Coordinated and direct engagement"
    },
    {
      "conditions": [],
      "definition": "Product-owned Project Reference-Frame Basis projects the outcome and work-authority decision selected under existing ownership by Goals, Product, requirements, accepted design, ticket, release law or an admitted bounded proxy. It cites every material configuration source without becoming a new local-axiom authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1136,
          "quote": "The Product-owned Project Reference-Frame Basis\n(PRODUCT_DEFINITION §7) projects that decision",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F12.%20Complete%20engagement%20transition%2F1.%20Existing%20authority%20selects%20the%20basis",
          "start_line": 1135
        }
      ],
      "key": "project_frame_basis",
      "label": "Project Reference-Frame Basis"
    },
    {
      "conditions": [],
      "definition": "Bounded activation packet based on REFERENCE_FRAME §11. Worker activation additionally binds sufficient execution intake; Reviewer activation binds exact claim and assurance conditions; Executive activation binds current Product-role map, mandate, evaluation frontier, result and triage ledger, priority and boundary policy, conjunction and disposition grant.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1679,
          "quote": "Every activation first carries the generic binding of REFERENCE_FRAME §11\n(minimal activation binding).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F19.%20Baseline-specific%20basis%20and%20activation%20additions%2FActivation%20additions",
          "start_line": 1672
        }
      ],
      "key": "activation_packet",
      "label": "Generic and frame-specific activation binding"
    },
    {
      "conditions": [],
      "definition": "Bounded information projections for Worker activation, activation refusal, work result, Reviewer activation, review result, specialist activation, specialist result, and disposition/checkpoint. These projections preserve distinct producers, consumers, coordinates, minimum material content and owning laws; they require no new artifact type.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1327,
          "quote": "the profile requires no new\nartifact type",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE%2F13.%20Handoff%20projection",
          "start_line": 1326
